import{_ as t,o as r,c as a,a4 as s}from"./chunks/framework.zh2mtvcP.js";const u=JSON.parse('{"title":"How these brands persuade","description":"","frontmatter":{},"headers":[],"relativePath":"research/brand-strategy.md","filePath":"research/brand-strategy.md","lastUpdated":1794245099000}'),o={name:"research/brand-strategy.md"};function i(n,e,c,l,d,h){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="how-these-brands-persuade" tabindex="-1">How these brands persuade <a class="header-anchor" href="#how-these-brands-persuade" aria-label="Permalink to &quot;How these brands persuade&quot;">​</a></h1><p><strong>Start here:</strong> compare the brand’s personality with the evidence it uses to earn trust. These are interpretations of public pages reviewed November 9, 2026—not declared brand strategies, customer diagnoses, or proof of sales impact.</p><h2 id="archetypes-a-storytelling-lens" tabindex="-1">Archetypes: a storytelling lens <a class="header-anchor" href="#archetypes-a-storytelling-lens" aria-label="Permalink to &quot;Archetypes: a storytelling lens&quot;">​</a></h2><p>An archetype is a recurring character or story pattern used to organize a brand’s voice. We use <strong>Sage</strong> for understanding, <strong>Creator</strong> for making something distinctive, and <strong>Everyperson</strong> for relatability and belonging. These are a small selection from the Mark–Pearson branding framework; names vary across versions. They are not fixed personality tests for companies. <a href="https://carolspearson.com/about/the-pearson-12-archetype-system-human-development-and-evolution" target="_blank" rel="noreferrer">Carol S. Pearson’s framework</a>.</p><table tabindex="0"><thead><tr><th>Competitor</th><th>Tentative reading</th><th>Evidence to inspect</th><th>Lesson to test</th></tr></thead><tbody><tr><td><a href="/white-tee-research/competitors/asket.html#archetype-persuasiveness">ASKET</a></td><td>Sage, with Creator cues</td><td>Product specifications, sourcing explanations, continuous refinement</td><td>Can specific facts make a plain tee worth its price?</td></tr><tr><td><a href="/white-tee-research/competitors/son-of-a-tailor.html#archetype-persuasiveness">Son of a Tailor</a></td><td>Creator, with Sage cues</td><td>Custom-fit process and production expertise</td><td>Does fit personalization solve a meaningful customer problem?</td></tr><tr><td><a href="/white-tee-research/competitors/true-classic.html#archetype-persuasiveness">True Classic</a></td><td>Everyperson, with aspirational confidence cues</td><td>Everyday fit problems, customer try-ons, accessible language</td><td>Do shoppers recognize themselves in the examples?</td></tr></tbody></table><p>Each profile links the underlying observations. More campaign and customer research could change these readings.</p><h2 id="cialdini-s-seven-principles" tabindex="-1">Cialdini’s seven principles <a class="header-anchor" href="#cialdini-s-seven-principles" aria-label="Permalink to &quot;Cialdini’s seven principles&quot;">​</a></h2><p>Robert Cialdini’s framework describes recurring influences on agreement and choice. In plain language:</p><table tabindex="0"><thead><tr><th>Principle</th><th>What to look for</th></tr></thead><tbody><tr><td>Reciprocity</td><td>Useful help or value offered before asking for something</td></tr><tr><td>Commitment &amp; consistency</td><td>A voluntary prior choice that a later action follows through on</td></tr><tr><td>Social proof</td><td>Evidence of what other people do or recommend</td></tr><tr><td>Authority</td><td>Relevant, credible expertise</td></tr><tr><td>Liking</td><td>Affinity with the people communicating</td></tr><tr><td>Scarcity</td><td>A genuinely limited opportunity or availability</td></tr><tr><td>Unity</td><td>A meaningful shared identity: “one of us”</td></tr></tbody></table><p>Sources: <a href="https://www.influenceatwork.com/7-principles-of-persuasion/" target="_blank" rel="noreferrer">Cialdini’s seven principles</a> and <a href="https://cialdini.com/principles/unity" target="_blank" rel="noreferrer">Unity explained</a>.</p><h2 id="what-the-first-three-show" tabindex="-1">What the first three show <a class="header-anchor" href="#what-the-first-three-show" aria-label="Permalink to &quot;What the first three show&quot;">​</a></h2><p><strong>Most visible:</strong> social proof across all three; expertise cues at ASKET and Son of a Tailor; relatability at True Classic. See the profile tables for evidence and limits.</p><p><strong>Not established in this sample:</strong> strong commitment/consistency or unity mechanisms. A paid membership alone does not establish unity. A seasonal discount alone does not establish scarcity. Custom sizing is not automatically commitment, and a guarantee primarily reduces risk rather than creating reciprocity.</p><h2 id="use-it-for-our-project" tabindex="-1">Use it for our project <a class="header-anchor" href="#use-it-for-our-project" aria-label="Permalink to &quot;Use it for our project&quot;">​</a></h2><p>Choose one competitor and complete this sentence:</p><blockquote><p>I noticed <strong>[specific evidence + source]</strong>. I interpret it as <strong>[archetype or principle]</strong> because <strong>[reason]</strong>. For our tee, I would test <strong>[small change]</strong> by checking <strong>[observable result]</strong>.</p></blockquote><p>Example: show actual fabric weight and a close-up beside a vague quality claim, then ask five classmates which version better explains the price. This tests clarity; it does not establish a sales lift. Use real reviews, substantiated claims, and honest availability.</p><p><a href="/white-tee-research/">← Research homepage</a> · <a href="/white-tee-research/our-brand.html">Our brand</a></p>',18)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
